package main

// land_ledgers.go is the evidence ledgers: a generated ledger the lander does not own
// (docs/SPEC-LANDING.md, the ledgers). docs/roadmap-evidence/fixed-<leg>.sexp is one entry
// per card, regenerated by the repository that owns it, the same shape as the roadmap data
// (docs/fixes.sexp, docs/roadmap.sexp) the lander already merges entry by entry
// (landsexp.go). The lander merges a conflict there instead of treating it as the card's own:
// both sides' entries are kept, in file order, no duplicate, and the merge is committed. An
// entry the lander cannot merge (a malformed one) is the lander's own failure, stopped with
// the conflict-kind ledger, never reworked at the tip.

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"slices"
	"strconv"
	"strings"

	"github.com/mas-bandwidth/nova-sprint/internal/cardgen"
	"github.com/mas-bandwidth/nova-tools/pkg/gitrun"
	"github.com/mas-bandwidth/nova-tools/pkg/roadmap"
	"github.com/mas-bandwidth/nova-tools/pkg/sexp"
)

// evidenceEntries is a decoded evidence ledger's records: each entry keyed by its id
// (its first two atoms, "<kind>:<id>"), each as a canonical printed value, so a record
// compares across the sides of a merge. An id met twice is an error.
func evidenceEntries(file string, data []byte) (map[string]string, error) {
	top, err := sexp.Read(file, data, landDataLimits)
	if err != nil {
		return nil, err
	}
	if top.Kind != sexp.List || len(top.List) < 1 || top.List[0].Kind != sexp.Symbol || top.List[0].Value != "evidence" {
		return nil, errors.New("want one (evidence \"v1\" ...) form")
	}
	out := map[string]string{}
	for i, f := range top.List {
		if f.Kind != sexp.Keyword || f.Value != "items" || i+1 >= len(top.List) {
			continue
		}
		items := top.List[i+1]
		if items.Kind != sexp.List {
			return nil, errors.New(":items is not a list")
		}
		for _, it := range items.List {
			if it.Kind != sexp.List || len(it.List) < 2 || it.List[1].Kind != sexp.String {
				return nil, errors.New("an entry is not (<kind> <id> ...)")
			}
			key := it.List[0].Value + ":" + it.List[1].Value
			if _, dup := out[key]; dup {
				return nil, fmt.Errorf("%s is named twice", key)
			}
			out[key] = formString(it)
		}
	}
	return out, nil
}

// formString is an s-expression form as a canonical, comparable string (offsets dropped).
func formString(f sexp.Form) string {
	switch f.Kind {
	case sexp.List:
		parts := make([]string, len(f.List))
		for i, x := range f.List {
			parts[i] = formString(x)
		}
		return "(" + strings.Join(parts, " ") + ")"
	case sexp.String:
		return strconv.Quote(f.Value)
	case sexp.Keyword:
		return ":" + f.Value
	case sexp.Integer:
		return strconv.FormatInt(f.Int, 10)
	default:
		return f.Value
	}
}

// evidenceMerged holds the merged evidence data to what the two sides did, entry by entry,
// exactly as sexpEntriesMerged holds the roadmap data (landsexp.go): an entry all three
// share is the side's that changed it (both changing it differently is a conflict), one a
// side removed is gone, one a side added is there as added (both adding one id differently
// is a conflict), and nothing else is there.
func evidenceMerged(file string, base, ours, theirs, merged []byte) error {
	return entriesMerged(evidenceEntries, unionKeys[string], file, base, ours, theirs, merged)
}

// landDataLimits is the bound on a lander decode of the roadmap data (docs/fixes.sexp,
// docs/roadmap.sexp) and the evidence ledgers: the same shape as roadmap.Limits with
// room for a repository whose data stands past 512 KiB (the schema repository's
// docs/roadmap.sexp is 1,081,875 bytes), so the lander merges that data instead of
// refusing the card at the tip, round after round (tla/LandLedgers.tla, ResolveLand).
// Data past it is still refused whole, never truncated. It bounds the lander's own
// decode only: roadmap.Limits and every other caller (the generators, nova-work)
// keep theirs.
var landDataLimits = sexp.Limits{MaxBytes: 16 << 20, MaxNodes: 16 << 20, MaxDepth: roadmap.Limits.MaxDepth}

// entriesMerged holds the merged data to what the two sides did, entry by entry: an entry
// all three share is the side's that changed it (both changing it differently is a
// conflict), one a side removed is gone, one a side added is there as added (both adding
// one id differently is a conflict), and nothing else is there. It is the three-way merge
// frame the evidence and roadmap ledgers share: parse reads one side into records keyed by
// id, unionKeys their sorted keys. evidenceMerged (this file) and sexpEntriesMerged
// (landsexp.go) each call it with their own entry parse and key union.
func entriesMerged[V comparable](parse func(file string, data []byte) (map[string]V, error), unionKeys func(...map[string]V) []string, file string, base, ours, theirs, merged []byte) error {
	var e [3]map[string]V
	for i, side := range [][]byte{base, ours, theirs} {
		m, err := parse(file, side)
		if err != nil {
			return fmt.Errorf("a side does not decode: %s", oneLineErr(err))
		}
		e[i] = m
	}
	b, o, t := e[0], e[1], e[2]
	want := map[string]V{}
	for _, k := range unionKeys(b, o, t) {
		bv, inB := b[k]
		ov, inO := o[k]
		tv, inT := t[k]
		switch {
		case inB && inO && inT:
			switch {
			case ov == bv:
				want[k] = tv
			case tv == bv || tv == ov:
				want[k] = ov
			default:
				return fmt.Errorf("both sides change %s", k)
			}
		case inB:
			if inO && ov != bv || inT && tv != bv {
				return fmt.Errorf("one side removes %s and the other changes it", k)
			}
		case inO && inT && ov != tv:
			return fmt.Errorf("both sides add %s, differently", k)
		case inO:
			want[k] = ov
		default:
			want[k] = tv
		}
	}
	got, err := parse(file, merged)
	if err != nil {
		return fmt.Errorf("the merged data does not decode: %s", oneLineErr(err))
	}
	for _, k := range unionKeys(want, got) {
		wv, inW := want[k]
		gv, inG := got[k]
		switch {
		case !inG:
			return fmt.Errorf("the merged data lacks %s", k)
		case !inW:
			return fmt.Errorf("the merged data holds %s, which a side removed", k)
		case wv != gv:
			return fmt.Errorf("the merged data changes %s", k)
		}
	}
	return nil
}

// unionKeys is the keys of the maps, sorted, each once.
func unionKeys[V any](ms ...map[string]V) []string {
	var out []string
	for _, m := range ms {
		for k := range m {
			if !slices.Contains(out, k) {
				out = append(out, k)
			}
		}
	}
	slices.Sort(out)
	return out
}

// unionEvidenceSexp merges an evidence ledger at a merge whose base holds it (a content
// conflict): base, the tip's side (ours) and the card's (theirs), the same line merge as
// unionSexp (landsexp.go), held to the evidence decode instead of the roadmap decode.
func unionEvidenceSexp(file string, base, ours, theirs []byte) ([]byte, error) {
	var bodies [3][]string
	var closers [3]int
	var tail string
	for i, side := range [][]byte{base, ours, theirs} {
		body, k, t := splitClosers(string(side))
		if k == 0 {
			return nil, errors.New("a side does not end in a closing parenthesis")
		}
		closers[i], bodies[i] = k, strings.Split(body, "\n")
		if i == 1 {
			tail = t
		}
	}
	if closers[0] != closers[1] || closers[0] != closers[2] {
		return nil, fmt.Errorf("the sides end in %d, %d and %d closing parentheses, which is no entry added or removed", closers[0], closers[1], closers[2])
	}
	ko, io, err := lineEdits(bodies[0], bodies[1])
	if err != nil {
		return nil, err
	}
	kt, it, err := lineEdits(bodies[0], bodies[2])
	if err != nil {
		return nil, err
	}
	lines, err := mergeLineEdits(bodies[0], ko, kt, io, it)
	if err != nil {
		return nil, err
	}
	lines = tidyBlanks(bodies[0], lines)
	out := []byte(strings.Join(lines, "\n") + strings.Repeat(")", closers[0]-1) + tail)
	if err := evidenceMerged(file, base, ours, theirs, out); err != nil {
		return nil, err
	}
	return out, nil
}

// unionEvidenceSexpAdd merges an evidence ledger the base does not hold (an add/add
// conflict): the shared header and footer kept once, then the tip's entries then the card's,
// no duplicate.
func unionEvidenceSexpAdd(file string, ours, theirs []byte) ([]byte, error) {
	if bytes.Equal(ours, theirs) {
		return ours, nil
	}
	oh, oe, of, err := evidenceParts(file, ours)
	if err != nil {
		return nil, err
	}
	th, te, tf, err := evidenceParts(file, theirs)
	if err != nil {
		return nil, err
	}
	if !bytes.Equal(oh, th) || !bytes.Equal(of, tf) {
		return nil, errors.New("the two sides' headers or footers differ")
	}
	entries := append(append([][]byte{}, oe...), te...)
	var b bytes.Buffer
	b.Write(oh)
	for i, e := range entries {
		if i > 0 {
			b.WriteString("\n\n  ")
		}
		b.Write(e)
	}
	b.Write(of)
	out := b.Bytes()
	if err := evidenceAddMerged(file, ours, theirs, out); err != nil {
		return nil, err
	}
	return out, nil
}

// evidenceParts is an evidence ledger split at its :items list: the header (everything
// before the first entry, the list's own open parenthesis included), the entries' raw
// bytes in file order, and the footer (everything after the last entry, the closing
// parentheses included).
func evidenceParts(file string, data []byte) (header []byte, entries [][]byte, footer []byte, err error) {
	top, err := sexp.Read(file, data, landDataLimits)
	if err != nil {
		return nil, nil, nil, err
	}
	if top.Kind != sexp.List || len(top.List) < 1 || top.List[0].Kind != sexp.Symbol || top.List[0].Value != "evidence" {
		return nil, nil, nil, errors.New("want one (evidence \"v1\" ...) form")
	}
	for i, f := range top.List {
		if f.Kind != sexp.Keyword || f.Value != "items" || i+1 >= len(top.List) {
			continue
		}
		items := top.List[i+1]
		if items.Kind != sexp.List || len(items.List) == 0 {
			return nil, nil, nil, errors.New(":items is not a non-empty list")
		}
		header = data[:items.List[0].Offset]
		for _, it := range items.List {
			entries = append(entries, data[it.Offset:it.End])
		}
		footer = data[items.List[len(items.List)-1].End:]
		return header, entries, footer, nil
	}
	return nil, nil, nil, errors.New("the form names no :items")
}

// evidenceAddMerged holds an add/add merge to what the two sides added: both kept, no
// duplicate, and nothing else there.
func evidenceAddMerged(file string, ours, theirs, merged []byte) error {
	o, err := evidenceEntries(file, ours)
	if err != nil {
		return fmt.Errorf("a side does not decode: %s", oneLineErr(err))
	}
	t, err := evidenceEntries(file, theirs)
	if err != nil {
		return fmt.Errorf("a side does not decode: %s", oneLineErr(err))
	}
	m, err := evidenceEntries(file, merged)
	if err != nil {
		return fmt.Errorf("the merged data does not decode: %s", oneLineErr(err))
	}
	for k, ov := range o {
		if tv, ok := t[k]; ok && tv != ov {
			return fmt.Errorf("both sides add %s, differently", k)
		}
	}
	for k := range o {
		if _, ok := m[k]; !ok {
			return fmt.Errorf("the merged data lacks %s", k)
		}
	}
	for k := range t {
		if _, ok := m[k]; !ok {
			return fmt.Errorf("the merged data lacks %s", k)
		}
	}
	for k := range m {
		if _, inO := o[k]; !inO {
			if _, inT := t[k]; !inT {
				return fmt.Errorf("the merged data holds %s, which neither side added", k)
			}
		}
	}
	return nil
}

// conflictEntriesSaid is both sides' conflicting entries of an evidence ledger the lander
// could not resolve, as the judgment's tail (docs/SPEC-LANDING.md, the merge rule: a ledger
// conflict the lander cannot resolve stops the stream with the path and both entries in the
// judgment): the tip's (ours) entries the card lacks, then the card's (theirs) the tip
// lacks, each raw as it stands, so a malformed entry the strict reader refuses is named
// too. "" when the two sides hold the same entries.
func conflictEntriesSaid(ours, theirs []byte) string {
	o, t := evidenceSideEntries(ours), evidenceSideEntries(theirs)
	in := func(xs []string, e string) bool { return slices.Contains(xs, e) }
	var parts []string
	for _, e := range o {
		if !in(t, e) {
			parts = append(parts, "the tip's entry "+e)
		}
	}
	for _, e := range t {
		if !in(o, e) {
			parts = append(parts, "the card's entry "+e)
		}
	}
	if len(parts) == 0 {
		return ""
	}
	return "; " + strings.Join(parts, " and ")
}

// evidenceSideEntries is an evidence ledger's entry forms as raw text, one per :items
// member, read leniently: a dispatch macro or another byte the strict reader refuses still
// yields the entry it stands in, so a side the merge cannot decode still names what it
// holds (conflictEntriesSaid). Nil when the data names no :items list.
func evidenceSideEntries(data []byte) []string {
	s := string(data)
	i := strings.Index(s, ":items")
	if i < 0 {
		return nil
	}
	j := i + len(":items")
	for j < len(s) && (s[j] == ' ' || s[j] == '\t' || s[j] == '\n' || s[j] == '\r') {
		j++
	}
	if j >= len(s) || s[j] != '(' {
		return nil
	}
	return memberForms(s, j)
}

// memberForms is each direct (...) member of the list whose open parenthesis is at start,
// raw from its own open parenthesis to its own close, comments and strings honored.
func memberForms(s string, start int) []string {
	var out []string
	depth, formStart := 0, -1
	inStr, inComment := false, false
	for i := start; i < len(s); i++ {
		c := s[i]
		switch {
		case inComment:
			if c == '\n' {
				inComment = false
			}
		case inStr:
			if c == '\\' {
				i++
			} else if c == '"' {
				inStr = false
			}
		case c == ';':
			inComment = true
		case c == '"':
			inStr = true
		case c == '(':
			if depth == 1 && formStart < 0 {
				formStart = i
			}
			depth++
		case c == ')':
			depth--
			if depth == 1 && formStart >= 0 {
				out = append(out, s[formStart:i+1])
				formStart = -1
			}
			if depth == 0 {
				return out
			}
		}
	}
	return out
}

// stageEvidenceUnion resolves the evidence ledgers among a merge's unmerged paths: each
// one's merged text written and staged. rest is the paths without them, data the ones
// resolved; card is why one is refused (a malformed entry, the lander's own failure, which
// the merge reports with the conflict-kind ledger and stops the stream), env a git failure
// that is not the card's.
func (l *lander) stageEvidenceUnion(ctx context.Context, dir string, paths []string) (rest, data []string, card, env string) {
	for _, p := range paths {
		if !cardgen.EvidenceLedger(p) {
			rest = append(rest, p)
			continue
		}
		if q := onDiskLink(dir, []string{p}); q != "" {
			return nil, nil, p + " conflicts and " + q + " is a symlink, which the resolution would write through", ""
		}
		var sides [3][]byte
		baseMissing := false
		for i := range sides {
			res, err := gitrun.Run(ctx, gitrun.Options{C: dir, Env: l.a.gitEnv, OwnRepo: true}, "show", ":"+strconv.Itoa(i+1)+":"+p)
			if err != nil {
				if i == 0 {
					baseMissing = true
					continue
				}
				return nil, nil, p + " conflicts and has no stage " + strconv.Itoa(i+1) + " to resolve from (added or removed on one side)", ""
			}
			sides[i] = res.Stdout
		}
		var merged []byte
		var err error
		if baseMissing {
			merged, err = unionEvidenceSexpAdd(p, sides[1], sides[2])
		} else {
			merged, err = unionEvidenceSexp(p, sides[0], sides[1], sides[2])
		}
		if err != nil {
			// the evidence decoder or the line merge refused it: merged form by form
			// (land_forms.go), which also reads a ledger of bare (:id ...) forms, one a line,
			// as the schema repository writes them
			var base []byte
			if !baseMissing {
				base = sides[0]
			}
			byForm, ferr := mergeByForm(p, base, sides[1], sides[2])
			if ferr != nil {
				// the lander's own failure: stopped with the conflict-kind ledger, never a
				// rework, and the judgment carries both conflicting entries (docs/SPEC-LANDING.md,
				// the merge rule) so a mind sees what neither side could merge
				return nil, nil, p + " conflicts and " + err.Error() + "; by form, " + ferr.Error() + conflictEntriesSaid(sides[1], sides[2]), ""
			}
			merged = byForm
		}
		if err := os.WriteFile(filepath.Join(dir, filepath.FromSlash(p)), merged, 0o644); err != nil {
			return nil, nil, "", "the merged " + p + " could not be written: " + err.Error()
		}
		if _, err := l.git(ctx, dir, "add", "--", p); err != nil {
			return nil, nil, "", "the merged " + p + " could not be staged: " + firstLine("", err)
		}
		data = append(data, p)
	}
	return rest, data, "", ""
}
